from math import gcd

def max_groups(n):
    if n == 1:
        return 0, []
    groups = []
    for i in range(n - 1):
        for j in range(i + 1, n):
            if gcd(i + 1, j + 1) > 1:
                groups.append([i + 1, j + 1])
    _, leader = max([(gcd(i, j), i, j) for i in range(n) for j in range(i + 1, n)])
    for i in range(leader - n * (n - 2) // 2, n - n * (n - 2) // 2):  # required gaps
        for j in range((2 * i + 2) % n, n - 1, 2):
            conn = gcd(i + 1, j + 1) > 1
            if conn and [i + 1, j + 1] not in groups:
                groups.append([i + 1, j + 1])
                return len(groups), groups
    return len(groups), groups

