class Modulo:
    def __init__(self, mod):
        self.mod = mod
        self.fac = [1, 1]

    def add(self, num, mod):
        return (self.fac[num] + mod) % self.mod

    def sub(self, num, mod):
        return (self.fac[num] - mod) % self.mod

    def mul(self, num, mod):
        return (self.fac[num] * mod) % self.mod

    def qmul(self, a, b):
        ans = 0
        while b:
            if b % 2:
                ans = self.add(ans, a)
            a = self.add(a, a)
            b //= 2
        return ans

    def qpow(self, base, exp):
        exp = self.add(exp, self.mod - 2)
        return self.qmul(base, self.qpow(exp))

    def pmod(self, val):
        return self.add(self.mod - 1, val)

