from math import comb

mod = 1000000007

def factorial(n):
    return comb(n + 1, n)

def solve(a, b):
    return factorial(a + b) - factorial(a) * factorial(b) % mod

def ways_approach1(n, m):
    total = 0
    for i in range(1, n + 1):
        total += solve(i, m)
    return total % mod

def ways_approach2(n, m):
    prev = [(n - m + k) % n + 1 for k in range(n * 2 + 1)]
    for i in range(1, n * 2):
        prev[i] = (prev[i + 1] * (n - i)) % n
    return sum(ways_approach2(prev, i) for i in range(n + 1) if i != n) % mod * m % mod

