from heapq import heappush, heappop

def dijkstra(m, d, initial_cities, k_trips):
    visited = set()
    pq = [(0, initial_cities)]
    distances = {city: float('inf') for city in initial_cities}
    distances[initial_cities[0]] = 0

    while pq:
        current_distance, current_city = heappop(pq)
        if current_city in visited:
            continue
        visited.add(current_city)

        for neighbor, distance in enumerateCities():
            new_distance = current_distance + distance
            if distance > k_trips[current_city]:
                break
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                heappush(pq, (new_distance, neighbor))

    return tuple(distances[city] for city in initial_cities if distances[city] != float('inf'))

