from collections import defaultdict

def assign_buttons(nums, speed_dial_k):
    prefix_sums = [[0] * len(nums) for _ in range(speed_dial_k)]
    dp = [[float('inf')] * len(nums) for _ in range(speed_dial_k)]

    # Initialize prefix sums for the first entry
    for i in range(len(nums)):
        prefix_sums[0][i] = len(nums) - i - 1

    # Fill in the prefix sums based on the previous entry's values
    for k in range(1, speed_dial_k):
        for i in range(len(nums)):
            prefix_sums[k][i] = min(prefix_sums[k-1][j] + (i - j - 1) for j in range(max(0, i - 1 - k), min(len(nums), i + 1 - k)))

    # Initialize DP table
    for i in range(len(nums) - 1, -1, -1):
        for k in reversed(range(speed_dial_k)):
            for j in range(i, len(nums)):
                dp[k][i] = min(dp[k][i], dp[k % speed_dial_k][j] + sequential_presses(nums, prefix_sums, j))

    return dp[(speed_dial_k - 1) % speed_dial_k].pop()

def sequential_presses(nums, prefix_sums, start):
    presses = 0
    for i in range(start, len(nums)):
        presses += prefix_sums[(k := (k + 1) % speed_dial_k)][i] + (i - 1 - start + 1 if k > 0 else 0)
    return presses

