import math

def find_max_groups(apples):
    if apples < 2:
        return 0
    if apples % 2 != 0:
        # No groups possible with odd apples
        return 0
    max_groups = 0
    remaining = apples
    group_size = 2
    while remaining > 0:
        # Remove pairs of numbers with a greatest common divisor of 1
        while remaining >= group_size-1:
            current_num, next_num = remaining // group_size, remaining % group_size
            if math.gcd(current_num, next_num) == 1:
                remaining -= group_size
            else:
                max_groups += 1
                remaining -= group_size
            if remaining <= group_size // 2:
                return max_groups
    return max_groups

