def solve(s):
    n = len(s)
    mod = 10**9 + 7
    dp = [[0] * (n//2) for _ in range(n//2)]

    @lru_cache(None)
    def dfs(i, j):
        if i >= j:
            return 1
        if j - i + 1 < n//2:
            return 0
        if s[i] != s[j-1]:
            return 0
        if dp[i][j] != 0:
            return dp[i][j]
        k = (j - i + 1) // 2
        if k & 1:
            dp[i][j] = (dfs(i + 1, j - k + 1) + dfs(i, j - k) * 2 + dfs(i + k // 2, j - k // 2) * 2) % mod
        else:
            dp[i][j] = dfs(i + k // 2, j - k // 2)
        return dp[i][j]

