            new_min_distance = float('inf')
            for j in prev_state_repeated:
                min_dist = max(min_distance, 
                              point_to_line(j, repeats[j]))
                prev_distance = calculate_distance(prev_state[j][0], prev_state[j][1], repeat[0], repeat[1])
                if prev_distance <= min_dist:
                    min_dist = prev_distance
                new_min_distance = min(new_min_distance, min_dist)

        new_repeats.append(repeat)
        min_distance = new_min_distance
    return set(repeats + new_repeats)

def connect_repeater(repeat, j):
    i_line = calculate_distance(repeat[0], repeat[1], j[0], j[1])
    k_line = math.sqrt(4 * i_line ** 2 - j[1] ** 2)
    return [ repeat[0] + k_line, repeat[1] + math.sqrt(k_line ** 2 - i_line ** 2) ]

def point_to_line(point, line):
    j = line[0][1] - line[1][1]
    a = line[0][0] - line[1][0]
    s = point[0]*a - point[1]*j - point[0]*a + point[1]*j
    if s >= 0 and s <= a*j:
        rezult = math.sqrt(point[0]**2 + point[1]**2 - (point[0] - j)**2)
    return rezult

