from itertools import combinations

def check_collinear(p1, p2, p3):
    return (p1[0] * p2[1] + p2[0] * p3[1] + p3[0] * p1[1]) == (p1[1] * p2[0] + p2[1] * p3[0] + p3[1] * p1[0])

def find_non_collinear_points(locations):
    civilisations = []
    points = []

    for i, j, k, l in locations:
        if k == 0:
            civilisations.append((i, j))
        else:
            points.append((i, j))

    # Check if all points belong to a single civilisation
    if len(set([c[0] for c in civilisations])) > 1:
        return "Impossible"

    # Remove Civilisations from Points
    for i, j in civilisations:
        points = [(x, y) for x, y in points if any(abs(x - i) + abs(y - j) <= 1)]

    # Generate all combinations of points
    all_combinations = combinations(range(len(points)), 2)

    # Checking for Non-Collinear Points pairs
    non_collinear_combinations = [combo for combo in all_combinations if not check_collinear(*combo)]

    if non_collinear_combinations:
        return len(non_collinear_combinations)
    else:
        return "Impossible"

