from functools import lru_cache

def min_ink_needed(n, m, a, b):
    @lru_cache(maxsize=None)
    def dp(i, prev_open, prev_close):
        if i == 0:
            return 0
        cost = 0
        if prev_open:
            cost += b[i-1]
        else:
            cost += a[i-1]
        return min(dp(i-1, prev_close, True) + cost, dp(i-1, True, False) + min(a[i-1], b[i-1]))

    return dp(m, False, False)

