def KMP_table(pattern):
    n = len(pattern)
    lps = [0] * n
    j = 0
    for i in range(1, n):
        while j > 0 and pattern[i] != pattern[j]:
            j = lps[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
        lps[i] = j
    return lps

class Solution:
    def numWays(self, s: str) -> int:
        s = list(s)
        k1, k2, k3 = 0, 0, 0
        previousPre = '*'
        prevIndexSet2 = set()
        for i in range(len(s)):
            if s[i] == previousPre:
                k1 += 1
                prevIndexSet2.add(2 * (i - k3))
            else:
                k1 = 1
                previousPre = s[i]
                prevIndexSet2.clear()
                if i == len(s) - 1:
                    k3 = i + 1
            if i % 2 == 0 and (i + 1 not in prevIndexSet2) and k1 < (len(s) - i) // 2:
                lps = KMP_table(s[i + 1:i + 1 + (len(s) - i) // 2])
                for i in range(len(lps)):
                    if s[i + 1] == s[i - lps[i]]:
                        prevIndexSet2.add(2 * (i - lps[i]) + 2)
        return 0 if len(prevIndexSet2) == 0 else pow(len(s) - len(prevIndexSet2), 2, 10**9 + 7)
