        for j in range(i + 1, len(locations)):
            if not are_collinear(*points[i], *points[j]):
                connections[(i, j)] = connections.get((i, j), []) + [points[i], points[j]]

    # Find the start and end points for each connection
    starts, ends = set(), set()
    for (i, j), points in connections.items():
        starts.update([p[0] for p in points])
        ends.update([p[1] for p in points])

    # Check if we have at least the number of points needed
    if len(starts) < len(connections) // 2 or len(ends) < len(connections) // 2:
        return "Impossible"

    # Sort by y-coordinate, then by x-coordinate to eliminate vertical lines
    sorted_points = sorted(points, key=lambda p: (p[1], p[0]))

    # Create roads
    roads = []
    last_start = -1
    for i, pt in enumerate(sorted_points):
        if len(roads) > max_civilization:
            return "Impossible"
        if i == 0 or sorted_points[i - 1][1] == pt[1]: 
            if last_start == -1 or sorted_points[i - 1][0] != sorted_points[i][0]:
                roads.append((last_start, i))
            last_start = i

