import math

def find_difficulty(n, m, locked_doors):
    lock_counts = {}
    for x1, y1, x2, y2 in locked_doors:
        if y1 != y2:
            x = x1 + y1
            y_diff = abs(y1 - y2)
            if (x, y_diff) in lock_counts:
                lock_counts[(x, y_diff)] += 1
            else:
                lock_counts[(x, y_diff)] = 1
        else:
            if x1 != x2:
                y = (x1 + x2) // 2
                x_diff = 0
                y_diff = y1 - y
                if (x1, y_diff) in lock_counts:
                    lock_counts[(x1, y_diff)] += 1
                else:
                    lock_counts[(x1, y_diff)] = 1
    non_zero_counts = len([count for count in lock_counts.values() if count > 0])
    return math.log(non_zero_counts + 1, 2)

